import React, { useEffect } from 'react';

const FeaturedSection = () => {
    useEffect(() => {
        // 1. Scroll Reveal Handler
        const revealSection = () => {
            const section = document.getElementById('features');
            if (!section) return;

            const windowHeight = window.innerHeight;
            const elementTop = section.getBoundingClientRect().top;
            const elementVisible = 150; // Triggers when 150px of the section is visible

            if (elementTop < windowHeight - elementVisible) {
                section.classList.add('active');
            }
        };

        // 2. Parallax Handler for background elements (.pl)
        const handleParallax = () => {
            const parallaxElements = document.querySelectorAll('#features .pl');
            const scrolled = window.scrollY;

            parallaxElements.forEach((el) => {
                const speed = el.getAttribute('data-speed') || 0.2;
                el.style.transform = `translateY(${scrolled * speed}px)`;
            });
        };

        // Combine into a single scroll event handler
        const handleScroll = () => {
            revealSection();
            handleParallax();
        };

        // Attach listener to window scroll
        window.addEventListener('scroll', handleScroll);

        // Run immediately on mount so it reveals right away if it's already on screen
        revealSection();
        handleParallax();

        // Clean up listeners when component unmounts
        return () => {
            window.removeEventListener('scroll', handleScroll);
        };
    }, []);

    return (
        <section id="features" className="reveal">
            <div className="parallax-field">
                <div
                    className="pl emblem-ghost"
                    data-speed="0.2"
                    style={{ top: '40px', right: '4%', width: '90px', height: '90px', color: '#391B13' }}
                >
                    <svg>
                        <use href="#emblem-mono" />
                    </svg>
                </div>
                <div
                    className="pl"
                    data-speed="0.15"
                    style={{
                        bottom: '-100px',
                        left: '-120px',
                        width: '360px',
                        height: '360px',
                        borderRadius: '50%',
                        background: 'radial-gradient(circle, rgba(254,198,15,0.18), rgba(254,198,15,0) 70%)'
                    }}
                ></div>
            </div>
            <div className="wrap">
                <div className="section-head center">
                    <span className="eyebrow" style={{ justifyContent: 'center' }}>What Sandwich does</span>
                    <h2>Built for every layer of your operation</h2>
                    <p className="lede">
                        A fully integrated platform where procurement, stock control, processing, kitchen, POS, and
                        finance share real-time data with department-level validation at every handoff.
                    </p>
                </div>
                <div className="feat-grid">
                    <div className="feat-card">
                        <div className="feat-icon">
                            <svg viewBox="0 0 24 24" fill="none" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M6 3v7a3 3 0 006 0V3M9 10v11M18 3c-2 2-2 5 0 7v8" />
                            </svg>
                        </div>
                        <h3>Kitchen &amp; Processing</h3>
                        <p>
                            Recipes with AI yield calculation, kitchen display system, 3D kitchen activity view, and formal
                            validation before stock updates.
                        </p>
                    </div>
                    <div className="feat-card">
                        <div className="feat-icon">
                            <svg viewBox="0 0 24 24" fill="none" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M3 9l9-6 9 6v10a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                                <path d="M9 21V12h6v9" />
                            </svg>
                        </div>
                        <h3>Inventory &amp; Procurement</h3>
                        <p>
                            Purchase orders, GRNs, blind stock counts, reorder alerts, and AI invoice OCR that auto-populates
                            receiving forms.
                        </p>
                    </div>
                    <div className="feat-card">
                        <div className="feat-icon">
                            <svg viewBox="0 0 24 24" fill="none" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M3 17l5-5 4 4 8-8M20 8v8h-8" />
                            </svg>
                        </div>
                        <h3>Finance &amp; AI Analytics</h3>
                        <p>
                            Automated daily P&amp;L, cash flow, budget-vs-actual, and BCG-matrix menu profitability — synced to
                            QuickBooks or Xero.
                        </p>
                    </div>
                    <div className="feat-card">
                        <div className="feat-icon">
                            <svg viewBox="0 0 24 24" fill="none" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                                <circle cx="9" cy="7" r="3.2" />
                                <path d="M2 21c0-4 3-6.5 7-6.5S16 17 16 21" />
                                <path d="M17 8.5c1.6.3 2.8 1.5 2.8 3.2M22 21c0-2.8-1.7-4.8-4-5.6" />
                            </svg>
                        </div>
                        <h3>HR, POS &amp; Multi-Branch</h3>
                        <p>
                            Role-based access across every department, full point-of-sale with split payments, and a Super Admin view
                            across branches.
                        </p>
                    </div>
                </div>

                <div className="ai-strip">
                    <div className="ai-item">
                        <div className="t">AI Invoice OCR</div>
                        <div className="d">Scans supplier invoices and auto-fills GRN fields for human review.</div>
                    </div>
                    <div className="ai-item">
                        <div className="t">14-Day Sales Forecasting</div>
                        <div className="d">Self-improving demand prediction by branch and menu item.</div>
                    </div>
                    <div className="ai-item">
                        <div className="t">Predictive Ordering</div>
                        <div className="d">Forecast → recipe explosion → supplier-ready draft PO.</div>
                    </div>
                    <div className="ai-item">
                        <div className="t">Variance Detection</div>
                        <div className="d">Flags price spikes, unusual volumes, and overproduction patterns.</div>
                    </div>
                </div>

                <div className="shot-gallery">
                    <div className="shot-gallery-card">
                        <img
                            src="data:image/jpeg;base64,"
                            alt="Approval and workflow queue inside Sandwich"></img>
                        <h4>Approval &amp; Workflow</h4>
                        <p>Every purchase and supplier onboarding routes through a clear pending / approved / rejected queue.</p>
                    </div>
                    <div className="shot-gallery-card">
                        <img
                            src="data:image/jpeg;base64,"
                            alt="Cost analytics food cost ratio trend"></img>
                        <h4>Cost Analytics</h4>
                        <p>Food cost ratio, cost per dish, and target variance tracked automatically against your goals.</p>
                    </div>
                    <div className="shot-gallery-card">
                        <img
                            src="data:image/jpeg;base64,"
                            alt="Internal team chat across branches and departments"></img>
                        <h4>Team Chat</h4>
                        <p>Branch, department, and role-based channels keep every shift in sync - on web and mobile.</p>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default FeaturedSection;